def max_polygon_area(segments):
    def shoelace_formula(coords):
        n = len(coords)
        area = 0.5 * abs(sum(x * y - y * x for x, y in zip(coords, coords[1:] + coords[:1])))
        return area

    def is_convex(polygon):
        n = len(polygon)
        direction = None
        for i in range(n):
            p1, p2, p3 = polygon[i], polygon[(i + 1) % n], polygon[(i + 2) % n]
            cross_product = (p2[0] - p1[0]) * (p3[1] - p1[1]) - (p2[1] - p1[1]) * (p3[0] - p1[0])
            if cross_product == 0:
                continue
            elif cross_product > 0:
                new_direction = 'cw'
            else:
                new_direction = 'ccw'
            if direction is None:
                direction = new_direction
            elif direction != new_direction:
                return False
        return True

    max_area = 0
    for r in range(3, len(segments) + 1):
        for combo in combinations(segments, r):
            # Sort segments by length to form triangles or polygons
            combo = sorted(combo, reverse=True)
            # Try all possible orderings of segments to form polygons
            for perm in permutations(combo):
                polygon = []
                for i in range(len(perm)):
                    if i == 0:
                        polygon.append((0, 0))
                    else:
                        last_x, last_y = polygon[-1]
                        next_x, next_y = perm[i][0], perm[i][1]
                        polygon.append((last_x + next_x, last_y + next_y))
                if is_convex(polygon):
                    area = shoelace_formula(polygon)
                    if area > max_area:
                        max_area = area
    return max_area

