import math

def max_polygon_area(sides):
    def shoelace_formula(coords):
        n = len(coords)
        area = 0.5 * abs(sum(coords[i][0] * coords[(i + 1) % n][1] - coords[(i + 1) % n][0] * coords[i][1] for i in range(n)))
        return area

    def valid_polygon(coords):
        n = len(coords)
        if n < 3:
            return False
        for i in range(n):
            x1, y1 = coords[i]
            x2, y2 = coords[(i + 1) % n]
            x3, y3 = coords[(i + 2) % n]
            if (y2 - y1) * (x3 - x2) == (y3 - y2) * (x2 - x1):
                return False
        return True

    max_area = 0
    for r in range(3, len(sides) + 1):
        for combination in itertools.combinations(sides, r):
            coords = [(sum(combination[:i]), sum(combination[i:i+2])) for i in range(0, len(combination), 2)]
            if valid_polygon(coords):
                area = shoelace_formula(coords)
                if area > max_area:
                    max_area = area

    return round(max_area, 5)

